#!/usr/bin/env node
'use strict';
/*
 * دال — پلتفرم هوشمند املاک (نسخه‌ی تک‌فایل)  ·  نسخه‌ی ساخت: 2af810256b30
 * نیازمند Node.js ۲۲٫۱۳ یا بالاتر. بدون npm install.
 *
 *   node dal.js                       اجرای سایت (پورت ۳۰۰۰؛ متغیر PORT)
 *   node dal.js admin 09123456789     ساخت مدیر      |  stats | backup | reset-password
 *
 * داده‌ها در پوشه‌ی data کنار همین فایل ذخیره می‌شوند (متغیر DAL_DATA_DIR برای تغییر).
 * این فایل خودش را در پوشه‌ی .dal-app کنار فایل باز می‌کند (فقط وقتی نسخه عوض شده باشد).
 */
const fs = require('node:fs');
const path = require('node:path');
const { spawn } = require('node:child_process');

const [maj, min] = process.versions.node.split('.').map(Number);
if (maj < 22 || (maj === 22 && min < 13)) { console.error('دال به Node.js 22.13 یا بالاتر نیاز دارد. نسخه‌ی فعلی: ' + process.version); process.exit(1); }

const VERSION = "2af810256b30";
const FILES = {"public/css/app.css":"","public/fonts/Vazirmatn.woff2":"","public/icon.svg":"","public/img/bg-blur-day.jpg":"","public/img/bg-blur-night.jpg":"","public/img/hero-battle.jpg":"","public/img/hero-night.jpg":"","public/index.html":"","public/js/app.js":"","public/js/components.js":"","public/js/core.js":"","public/js/page-account.js":"","public/js/page-admin.js":"","public/js/page-auth.js":"","public/js/page-consult.js":"","public/js/page-home.js":"","public/js/page-listing.js":"","public/js/page-market.js":"","public/js/page-new.js":"","public/js/page-people.js":"","public/js/page-search.js":"","public/js/page-tools.js":"","public/js/shell.js":"","public/manifest.webmanifest":"","public/sw.js":"","public/vendor/leaflet/images/layers-2x.png":"","public/vendor/leaflet/images/layers.png":"","public/vendor/leaflet/images/marker-icon-2x.png":"","public/vendor/leaflet/images/marker-icon.png":"","public/vendor/leaflet/images/marker-shadow.png":"","public/vendor/leaflet/leaflet.css":"","public/vendor/leaflet/leaflet.js":"","server/analytics.js":"","server/art.js":"","server/articles.js":"","server/bootstrap.js":"","server/cli.js":"","server/db.js":"","server/extern.js":"","server/index.js":"","server/meta.js":"","server/nlp.js":"","server/seo.js":"","server/services.js":"","server/tiles.js":"","server/util.js":"","server/valuation.js":"","package.json":""};

const HOME = __dirname;
const APP = path.join(HOME, '.dal-app');
const stamp = path.join(APP, '.version');
if (!fs.existsSync(stamp) || fs.readFileSync(stamp, 'utf8') !== VERSION) {
  fs.rmSync(APP, { recursive: true, force: true });
  for (const [rel, b64] of Object.entries(FILES)) {
    const dest = path.join(APP, rel); fs.mkdirSync(path.dirname(dest), { recursive: true }); fs.writeFileSync(dest, Buffer.from(b64, 'base64'));
  }
  fs.writeFileSync(stamp, VERSION);
}
const cli = ['admin', 'reset-password', 'backup', 'stats'].includes(process.argv[2]);
const args = cli ? ['--no-warnings', path.join(APP, 'server', 'cli.js'), ...process.argv.slice(2)] : ['--no-warnings', path.join(APP, 'server', 'index.js')];
const child = spawn(process.execPath, args, { stdio: 'inherit', env: { ...process.env, DAL_DATA_DIR: process.env.DAL_DATA_DIR || path.join(HOME, 'data') } });
for (const s of ['SIGINT', 'SIGTERM']) process.on(s, () => child.kill(s));
child.on('exit', (code) => process.exit(code ?? 0));
